319	      ret = `>=${M}.${m}.${p}-${pr
320	      } <${M}.${+m + 1}.0-0`
321	    } else {
322	      // ~1.2.3 == >=1.2.3 <1.3.0-0
323	      ret = `>=${M}.${m}.${p
324	      } <${M}.${+m + 1}.0-0`
325	    }
326	
327	    debug('tilde return', ret)
328	    return ret
329	  })
330	}
