  const cases = [
    ['>01.02.03', '>1.2.3', true],
    ['>01.02.03', null, false],
    ['>= 1.2.3', '>=1.2.3', null],
    ['1.2.3', '1.2.3', {}],
    ['1.2.3', '1.2.3', { loose: false }],
