  t.plan(cases.length)
  for (const [range, expect, options] of cases) {
    if (expect === null) {
      t.throws(() => new Range(range, options), TypeError, 'strict boolean rejects leading zeros')
    } else {
      t.equal(new Range(range, options).range, expect, JSON.stringify(options))
